"""API request handling."""


def _validate_request(data, auth_token):
    """Validate request inputs before they are passed to the processor."""
    # Authenticate first so unauthenticated callers cannot probe payload rules.
    if not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")

    if data is None:
        raise ValueError("request data is required")


def handle_request(data, auth_token):
    """Authenticate, validate, and process an incoming API request."""
    _validate_request(data, auth_token)
    return process(data)

